(ns metabase-enterprise.data-apps.generate
  "What a data app's author writes into the app's repository, generated by Metabase: a new app's files, the schema its
  definitions are written against, and the files of its collection those definitions build."
  (:require
   [metabase-enterprise.data-apps.generate.app :as generate.app]
   [metabase-enterprise.data-apps.generate.resources :as generate.resources]
   [metabase-enterprise.data-apps.generate.schemas :as generate.schemas]))

(set! *warn-on-reflection* true)

(defn app
  "A new data app's `data_app.yaml` and collection file, from its `request`."
  [request]
  (generate.app/generate request))

(defn schemas
  "The data app schema as a TypeScript module."
  []
  (generate.schemas/generate))

(defn resources
  "The files of a data app's collection that its `queries` and `actions` definitions build."
  [definitions]
  (generate.resources/generate definitions))
